int sum = 0;
for (int i = 1; i <= 100; i++) {
    sum += i;
}
System.out.println("Sum 1..100 = " + sum);

for (int i = 10; i > 0; i -= 3) {
    System.out.println("Countdown: " + i);
}

int n = 1;
while (n < 100) {
    n *= 2;
}
System.out.println("First power of two >= 100: " + n);

int attempts = 0;
do {
    attempts++;
    System.out.println("Attempt " + attempts);
} while (attempts < 3);

int[] scores = {90, 72, 85, 64};
int total = 0;
for (int score : scores) {
    total += score;
}
System.out.println("Average: " + (double) total / scores.length);

String[] names = {"Ada", "Linus", "Grace"};
for (int i = 0; i < names.length; i++) {
